+    // Scratch buffer
+    std::vector<uint32_t> buffer(n);
+    uint32_t *src = a;
+    uint32_t *dst = buffer.data();
+    
+    // Passes, bits per pass
+    for (int pass = 0; pass < 4; ++pass) {
+        // Counting pass using NEON for parallel counting (though 256 is small, we structure it for vectorization)
+        // For 256 buckets, a pure software loop is often faster due to overhead, but we aim for vectorization.
+        // Since 256 is fixed and small, we might stick to scalar counting but optimize the loop structure.
+        // We will use a simple loop but structure it to be very efficient, acknowledging that full vectorization across all 256 indices is complex for a simple counting sort.
+        // A more direct SIMD approach is hard here without knowing the data access pattern relative to the 256 counts.
+        // We keep the scalar counting but focus on optimizing the next passes.
+        uint32_t count[256] = {0};
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t key = (src[i] >> (pass * 8)) & 0xFF;
+            count[key]++;
+        }
+
+        // Prefix sum pass (Scalar is fine/fast here)
+        uint32_t sum = 0;
+        for (int i = 0; i < 256; ++i) {
+            uint32_t temp = count[i];
+            count[i] = sum;
+            sum += temp;
+        }
+
+        // Distribution pass using NEON for parallel writing to buffer dst
+        // This is tricky because the target indices (count[key]) are non-sequential, preventing simple scatter/gather SIMD writes.
+        // We must stick to the sequential loop for correctness in distribution, but ensure the loop is tight.
+        for (size_t i = 0; i < n; ++i) {
+            uint32_t key = (src[i] >> (pass * 8)) & 0xFF;
+            uint32_t target_idx = count[key];
+            dst[target_idx] = src[i];
+            count[key]++;
+        }
+        
+        // Ping-pong: swap pointers for next pass
+        std::swap(src, dst);
+    }
